71	    void CaresPTRResolver::resolve(const std::string & ip, std::vector<std::string> & response)
72	    {
73	        in_addr addr;
74	
75	        inet_pton(AF_INET, ip.c_str(), &addr);
76	
77	        ares_gethostbyaddr(channel, reinterpret_cast<const void*>(&addr), sizeof(addr), AF_INET, callback, &response);
78	    }
